export function icuEastAsianWidth(codePoint) {   // u_getIntPropertyValue(c, UCHAR_EAST_ASIAN_WIDTH); out-of-range code points are not Unicode: U_EA_NEUTRAL
  if (!Number.isInteger(codePoint) || codePoint < 0 || codePoint > 0x10ffff) return 0;
  let low = 0, high = widths.length / 3 - 1;
  while (low <= high) {
    const middle = (low + high) >>> 1, at = middle * 3;
    if (codePoint < widths[at]) high = middle - 1;
    else if (codePoint > widths[at + 1]) low = middle + 1;
    else return widths[at + 2];
  }
  return 0;
}
export function icuCharMirror(codePoint) {   // u_charMirror(c): the Bidi_Mirroring_Glyph, or c itself
  let low = 0, high = mirrors.length / 2 - 1;
  while (low <= high) {
    const middle = (low + high) >>> 1, at = middle * 2;
    if (codePoint < mirrors[at]) high = middle - 1;
    else if (codePoint > mirrors[at]) low = middle + 1;
    else return mirrors[at + 1];
  }
  return codePoint;
}
